          marginRight: "8px",
          overflow: "hidden",
          opacity: isCollapsed ? 0 : 1,
        }}
      >
      <div className="absolute left-[24px] top-[24px] right-[55px] flex flex-col gap-[8px]">
        <div className="flex items-start gap-[6px]">
          <div className="relative shrink-0 size-[12px] opacity-50">
            <svg width="12" height="12" viewBox="0 0 8 6" fill="none" xmlns="http://www.w3.org/2000/svg">
              <rect x="0" y="0" width="8" height="1" fill="currentColor" />
              <rect x="0" y="2.5" width="8" height="1" fill="currentColor" />
              <rect x="0" y="5" width="8" height="1" fill="currentColor" />
            </svg>
          </div>
          <p className="font-['Urbanist',sans-serif] font-normal leading-none opacity-50 text-[12px] text-current whitespace-pre">
            Mihir&apos;s Workspace
          </p>
        </div>

        <p className="font-['Urbanist',sans-serif] font-semibold leading-none opacity-90 text-[16px] text-current whitespace-pre">
          SpreadJS Workbook
        </p>
      </div>

      <div className="absolute left-[24px] top-[155px] right-[24px] bottom-[384px] flex flex-col gap-[12px]">
        <div className="flex gap-[8px] items-center justify-between">
          <div className="font-['Geist_Mono',monospace] font-normal leading-[0] opacity-[0.52] text-[10px] text-current uppercase">
            <p className="leading-[1.5] whitespace-pre">Table of Contents</p>
          </div>
          <button
            onClick={() => setIsCollapsed(true)}
            className="flex gap-2.5 items-center p-2 rounded-full shrink-0 transition-colors -mr-2"
            style={{ filter: 'var(--app-icon-invert)' }}
          >
            <img
              src={imgTablerIconChevronLeftPipe}
              alt="Collapse"
              className="block max-w-none w-5 h-5"
            />
          </button>
        </div>

        <div className="flex flex-col">
          {tableOfContentsItems.map((item, index) => {
            const isActive = activeItem === item.id
            return (
              <button
                key={item.id}
                onClick={() => {
                  setActiveItem(item.id)
                  if (onActivateSheet) {
                    onActivateSheet(item.sheetName)
                  }
                }}
                className={`flex gap-[${isActive ? '8' : '10'}px] items-center ${isActive ? '' : 'opacity-[0.52]'} w-full text-left`}
              >
                <div className="flex flex-row items-center self-stretch">
                  <div className="h-full overflow-clip relative shrink-0 w-[12px]">
                    <div className="absolute bottom-0 left-1/2 top-0 -translate-x-1/2 w-px" style={{ backgroundColor: 'var(--app-text-muted)' }} />
                    {isActive && (
                      <div className="absolute bg-[#ffc31c] bottom-[7px] left-1/2 top-[7px] -translate-x-1/2 w-[2px]" />
                    )}
                  </div>
                </div>

                <div className="font-['Geist_Mono',monospace] font-normal text-[12px] text-current">
                  <p className="leading-[2.2] whitespace-pre">{item.label}</p>
                </div>
              </button>
            )
          })}
        </div>
      </div>

    </aside>
    </>
  )
}

themeContextContent:
"use client";

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';

type Theme = 'light' | 'dark' | 'system';
type ResolvedTheme = 'light' | 'dark';

interface ThemeContextType {
  theme: Theme;
  resolvedTheme: ResolvedTheme;
  setTheme: (theme: Theme) => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

const STORAGE_KEY = 'theme-preference';

function getSystemTheme(): ResolvedTheme {
  if (typeof window === 'undefined') return 'light';
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

function resolveTheme(theme: Theme): ResolvedTheme {
  if (theme === 'system') return getSystemTheme();
  return theme;
}

function applyTheme(resolved: ResolvedTheme) {
  if (typeof document === 'undefined') return;
  if (resolved === 'dark') {
    document.documentElement.classList.add('dark');
  } else {
    document.documentElement.classList.remove('dark');
  }
}

/** Read theme from URL ?theme= param (set by master sample app) */
function getUrlTheme(): Theme | null {
  if (typeof window === 'undefined') return null;
  const params = new URLSearchParams(window.location.search);
  const t = params.get('theme');
  if (t === 'light' || t === 'dark' || t === 'system') return t;
  return null;
}

function getInitialTheme(): Theme {
  if (typeof window === 'undefined') return 'light';
  // URL param takes priority (master app override), then localStorage
  return getUrlTheme() || (localStorage.getItem(STORAGE_KEY) as Theme) || 'light';
}

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setThemeState] = useState<Theme>(getInitialTheme);
  const [resolvedTheme, setResolvedTheme] = useState<ResolvedTheme>(() => resolveTheme(theme));

  const setTheme = useCallback((newTheme: Theme) => {
    setThemeState(newTheme);
    localStorage.setItem(STORAGE_KEY, newTheme);
  }, []);

  useEffect(() => {
    const resolved = resolveTheme(theme);
    setResolvedTheme(resolved);
    applyTheme(resolved);
  }, [theme]);

  // Sync with URL param on mount
  useEffect(() => {
    const urlTheme = getUrlTheme();
    if (urlTheme && urlTheme !== theme) {
      setThemeState(urlTheme);
      localStorage.setItem(STORAGE_KEY, urlTheme);
    }
  }, []);

  // Listen for postMessage from master app for live theme switching
  useEffect(() => {
    const handler = (event: MessageEvent) => {
      if (event.data?.type === 'theme-change' && event.data.theme) {
        const newTheme = event.data.theme as Theme;
        setThemeState(newTheme);
        localStorage.setItem(STORAGE_KEY, newTheme);
      }
    };
    window.addEventListener('message', handler);
    return () => window.removeEventListener('message', handler);
  }, []);

  useEffect(() => {
    if (theme !== 'system') return;
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const handler = () => {
      const resolved = getSystemTheme();
      setResolvedTheme(resolved);
      applyTheme(resolved);
    };
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, [theme]);

  return (
    <ThemeContext.Provider value={{ theme, resolvedTheme, setTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

/**
 * useTheme hook - works both with and without ThemeProvider.
 * When ThemeProvider is present, uses shared context.
 * When absent, manages its own state as a standalone fallback.
 */
export function useTheme(): ThemeContextType {
  const context = useContext(ThemeContext);

  // Standalone state — always called to satisfy rules of hooks
  const [localTheme, setLocalThemeState] = useState<Theme>(getInitialTheme);
  const [localResolved, setLocalResolved] = useState<ResolvedTheme>(() => resolveTheme(localTheme));

  const setLocalTheme = useCallback((newTheme: Theme) => {
    setLocalThemeState(newTheme);
    if (typeof window !== 'undefined') {
      localStorage.setItem(STORAGE_KEY, newTheme);
    }
  }, []);

  // Only apply side effects when running standalone (no provider)
  useEffect(() => {
    if (context) return;
    const resolved = resolveTheme(localTheme);
    setLocalResolved(resolved);
    applyTheme(resolved);
  }, [localTheme, context]);

  useEffect(() => {
    if (context) return;
    if (localTheme !== 'system') return;
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const handler = () => {
      const resolved = getSystemTheme();
      setLocalResolved(resolved);
      applyTheme(resolved);
    };
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, [localTheme, context]);

  if (context) return context;
  return { theme: localTheme, resolvedTheme: localResolved, setTheme: setLocalTheme };
}

themeToggleContent:
"use client";

import React from 'react';
import { useTheme } from './ThemeContext';

type ThemeOption = 'light' | 'dark' | 'system';

const SunIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="5" />
    <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42" />
  </svg>
);

const MoonIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
    <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
  </svg>
);

const MonitorIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
    <rect x="2" y="3" width="20" height="14" rx="2" ry="2" />
    <line x1="8" y1="21" x2="16" y2="21" />
    <line x1="12" y1="17" x2="12" y2="21" />
  </svg>
);

export function ThemeToggle() {
  const { theme, setTheme } = useTheme();

  const options: { value: ThemeOption; icon: React.ReactNode; label: string }[] = [
    { value: 'light', icon: <SunIcon />, label: 'Light' },
    { value: 'dark', icon: <MoonIcon />, label: 'Dark' },
    { value: 'system', icon: <MonitorIcon />, label: 'System' },
  ];

  return (
    <div style={{
      display: 'flex',
      flexDirection: 'row',
      alignItems: 'center',
      backgroundColor: 'var(--app-surface)',
      borderRadius: '8px',
      padding: '2px',
      gap: '2px',
    }}>
      {options.map((opt) => (
        <button
          key={opt.value}
          onClick={() => setTheme(opt.value)}
          title={opt.label}
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            width: '32px',
            height: '28px',
            borderRadius: '6px',
            border: 'none',
            cursor: 'pointer',
            backgroundColor: theme === opt.value ? 'var(--app-toggle-active-bg)' : 'transparent',
            color: theme === opt.value ? 'var(--app-text-primary)' : 'var(--app-text-tertiary)',
            transition: 'background-color 0.15s, color 0.15s',
          }}
        >
          {opt.icon}
        </button>
      ))}
    </div>
  );
}

