import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

spreadSheetsIoTypesContent:
// [SpreadJS] @mescius/spread-sheets-io ships no TypeScript declarations of its
// own. It is a side-effect plugin that augments the GC.Spread.Sheets namespace
// (the Workbook.import / export methods it enables are already declared in
// @mescius/spread-sheets). This ambient declaration lets the side-effect
// `import('@mescius/spread-sheets-io')` resolve without tripping noImplicitAny
// under strict mode.
declare module '@mescius/spread-sheets-io'

globalStylesContent:
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 222.2 84% 4.9%;
    --card: 0 0% 100%;
    --card-foreground: 222.2 84% 4.9%;
    --popover: 0 0% 100%;
    --popover-foreground: 222.2 84% 4.9%;
    --primary: 222.2 47.4% 11.2%;
    --primary-foreground: 210 40% 98%;
    --secondary: 210 40% 96.1%;
    --secondary-foreground: 222.2 47.4% 11.2%;
    --muted: 210 40% 96.1%;
    --muted-foreground: 215.4 16.3% 46.9%;
    --accent: 210 40% 96.1%;
    --accent-foreground: 222.2 47.4% 11.2%;
    --destructive: 0 84.2% 60.2%;
    --destructive-foreground: 210 40% 98%;
    --border: 214.3 31.8% 91.4%;
    --input: 214.3 31.8% 91.4%;
    --ring: 222.2 84% 4.9%;
    --radius: 0.5rem;

    /* App theme variables (light default) */
    --app-bg: #ffffff;
    --app-surface: #f5f5f5;
    --app-surface-border: #e0e0e0;
    --app-surface-hover: #e8e8e8;
    --app-border: #e0e0e0;
    --app-text-primary: #000000;
    --app-text-secondary: rgba(0,0,0,0.8);
    --app-text-tertiary: rgba(0,0,0,0.52);
    --app-text-muted: rgba(0,0,0,0.5);
    --app-toggle-active-bg: rgba(0,0,0,0.06);
    --app-sidebar-bg: #f0f0f0;
    --app-icon-invert: invert(1);
    --app-icon-active-invert: none;
  }

  .dark {
    --background: 222.2 84% 4.9%;
    --foreground: 210 40% 98%;
    --card: 222.2 84% 4.9%;
    --card-foreground: 210 40% 98%;
    --popover: 222.2 84% 4.9%;
    --popover-foreground: 210 40% 98%;
    --primary: 210 40% 98%;
    --primary-foreground: 222.2 47.4% 11.2%;
    --secondary: 217.2 32.6% 17.5%;
    --secondary-foreground: 210 40% 98%;
    --muted: 217.2 32.6% 17.5%;
    --muted-foreground: 215 20.2% 65.1%;
    --accent: 217.2 32.6% 17.5%;
    --accent-foreground: 210 40% 98%;
    --destructive: 0 62.8% 30.6%;
    --destructive-foreground: 210 40% 98%;
    --border: 217.2 32.6% 17.5%;
    --input: 217.2 32.6% 17.5%;
    --ring: 212.7 26.8% 83.9%;

    /* App theme variables (dark) */
    --app-bg: #000000;
    --app-surface: rgb(17,17,17);
    --app-surface-border: rgb(20,20,20);
    --app-surface-hover: rgb(34,34,34);
    --app-border: #141414;
    --app-text-primary: #ffffff;
    --app-text-secondary: rgba(255,255,255,0.8);
    --app-text-tertiary: rgba(255,255,255,0.52);
    --app-text-muted: rgba(255,255,255,0.5);
    --app-toggle-active-bg: rgba(255,255,255,0.08);
    --app-sidebar-bg: #0e0e0e;
    --app-icon-invert: none;
    --app-icon-active-invert: invert(1);
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* SpreadJS workbook styles - matching the sample shell */
.spreadjs-workbook {
  background: #ffffff;
  color: #111111;
  overflow: hidden;
}

.dark .spreadjs-workbook {
  background: #ffffff;
  color: #111111;
}

/* SpreadJS Velt comment overlays */
.velt-spreadjs-highlight {
  background-color: rgba(255, 212, 0, 0.36) !important;
  border: 1.5px solid rgba(255, 170, 0, 0.95) !important;
  border-radius: 2px !important;
}

velt-comment-text {
  cursor: pointer !important;
}

velt-comment-text:hover .velt-spreadjs-highlight,
velt-comment-text[comment-selected="true"] .velt-spreadjs-highlight,
velt-comment-text.velt-comment-selected .velt-spreadjs-highlight {
  background-color: rgba(255, 212, 0, 0.62) !important;
}

/* Helper Text Animation */
@keyframes pulse-subtle {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.7;
  }
}

.animate-pulse-subtle {
  animation: pulse-subtle 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

/* Collaboration cursor styling - Dark theme adjustments */
.collaboration-cursor__caret {
  border-left: 1px solid #ffffff;
  border-right: 1px solid #ffffff;
  margin-left: -1px;
  margin-right: -1px;
  pointer-events: none;
  position: relative;
  word-break: normal;
}

/* Render the username above the caret */
.collaboration-cursor__label {
  border-radius: 3px 3px 3px 0;
  color: #000000;
  background: #ffffff;
  font-size: 12px;
  font-style: normal;
  font-weight: 600;
  left: -1px;
  line-height: normal;
  padding: 0.1rem 0.3rem;
  position: absolute;
  top: -1.4em;
  user-select: none;
  white-space: nowrap;
}

nextConfigContent:
/** @type {import('next').NextConfig} */
const path = require('path');

// List of domains allowed to embed this app in an iframe
const allowList = [
  "'self'",
  "http://localhost:*",
  "https://*.vercel.app",
  "https://*.velt.dev",
  "https://*.mintlify.app",
].join(' ');

const EMBED_CSP = `frame-ancestors ${allowList}`;

const nextConfig = {
  reactStrictMode: false,
  turbopack: {
    root: path.join(__dirname, '..', '..', '..', '..', '..', '..'),
  },
  async headers() {
    return [
      {
        source: '/:path*',
        headers: [
          {
            key: 'Content-Security-Policy',
            value: EMBED_CSP,
          },
        ],
      },
    ]
  },
}

module.exports = nextConfig
